<?php
require __DIR__.'/bootstrap.php';requireAuth();
$error='';$items=[];
try{$pdo=db();$items=$pdo->query("SELECT pi.id,pi.product_id,pi.file_path,pi.alt_text,pi.is_primary,pi.sort_order,pi.created_at,p.name product_name FROM product_images pi JOIN products p ON p.id=pi.product_id ORDER BY pi.created_at DESC,pi.id DESC LIMIT 300")->fetchAll();}catch(Throwable $e){error_log('InYou medios: '.$e->getMessage());$error='No se pudo cargar la biblioteca de medios.';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Medios · InYou</title><link rel="stylesheet" href="/admin/style.css"><style>.wrap{max-width:1150px;margin:auto}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{background:#fff;border:1px solid #e7e5df;border-radius:12px;overflow:hidden}.card img{width:100%;aspect-ratio:1/1;object-fit:cover;display:block}.body{padding:12px}.body small{color:#777}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#e3eee6;font-size:12px;margin:6px 0}.error{margin:16px 0}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.grid{grid-template-columns:1fr}}</style></head><body class="dashboard"><?php adminSidebar('media');?><main class="content"><div class="wrap"><header><div>Hola, <?=h($_SESSION['admin_name']??'Administrador')?></div></header><div class="eyebrow">MEDIOS</div><h1>Biblioteca de imágenes</h1><p>Imágenes asociadas a productos. La carga y edición se realiza dentro de cada producto.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><div class="grid"><?php foreach($items as $img):?><article class="card"><img src="/<?=h($img['file_path'])?>" alt="<?=h($img['alt_text'])?>"><div class="body"><strong><?=h($img['product_name'])?></strong><br><?php if($img['is_primary']):?><span class="badge">Principal</span><br><?php endif;?><small><?=h($img['alt_text']?:'Sin texto alternativo')?></small><p><a href="/admin/images.php?product=<?=(int)$img['product_id']?>">Gestionar imagen →</a></p></div></article><?php endforeach;?><?php if(!$items):?><p>No hay imágenes cargadas.</p><?php endif;?></div></div></main></body></html>